metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses the catalogue and buys books online"

        bookshop = softwareSystem "Bookshop" "An online bookshop that sells books to customers" {
            webStore = container "Web Store" "Lets customers browse the catalogue and place orders" "Web application"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Service"
        }

        customer -> webStore "browses the catalogue and places orders" "HTTPS"
        webStore -> orderProcessor "submits new orders for processing" "gRPC"
    }

    views {
        systemContext bookshop "SystemContext" "System context for the Bookshop" {
            include *
            autoLayout
            title "System Context for Bookshop"
        }
    }
}
